import{_ as e,C as r,o,c as h,aj as d,E as l}from"./framework.js";const _=JSON.parse('{"title":"邮箱：邮箱地址 | Product / Mail | Documentation","description":"邮箱：邮箱地址 in Kooboo: 修改默认地址前会出现确认提示。默认地址会影响撰写页默认发件人、IMAP 授权码生成和日历邀请发送。","frontmatter":{"title":"邮箱：邮箱地址 | Product / Mail | Documentation","description":"邮箱：邮箱地址 in Kooboo: 修改默认地址前会出现确认提示。默认地址会影响撰写页默认发件人、IMAP 授权码生成和日历邀请发送。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/mail/addresses.html"}]]},"headers":[],"relativePath":"zh/product/mail/addresses.md","filePath":"product/mail/addresses.md","lastUpdated":1780999973000}'),s={name:"zh/product/mail/addresses.md"};function i(n,t,c,b,m,p){const a=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=d('<h1 id="邮箱-邮箱地址" tabindex="-1">邮箱：邮箱地址 <a class="header-anchor" href="#邮箱-邮箱地址" aria-label="Permalink to &quot;邮箱：邮箱地址&quot;">​</a></h1><blockquote><p>邮箱地址页决定账户能用哪些地址收发邮件，以及默认发件地址、签名、群组成员和转发目标。首次配置邮箱时，应先完成这一页。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>邮箱</strong> -&gt; 左侧 <strong>设置</strong> -&gt; <strong>邮箱地址</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kmail-settings/addresses</code></td></tr><tr><td>前端路由</td><td><code>/kmail-settings/addresses</code></td></tr><tr><td>前置条件</td><td>域名需出现在当前组织的域名列表中；在线服务环境提示邮箱面向使用 Kooboo DNS 的域名开放</td></tr></tbody></table>',4)),l(a,{src:"/product/mail/addresses-overview.png",alt:"邮箱地址设置：地址列表、默认地址和地址类型",width:"1120"}),t[1]||(t[1]=d('<h2 id="顶部工具栏" tabindex="-1">顶部工具栏 <a class="header-anchor" href="#顶部工具栏" aria-label="Permalink to &quot;顶部工具栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td><code>New Address</code></td><td>下拉创建普通地址、通配地址、群组、转发地址</td></tr><tr><td>默认地址</td><td>从非通配地址中选择默认发件地址</td></tr></tbody></table><p>修改默认地址前会出现确认提示。默认地址会影响撰写页默认发件人、IMAP 授权码生成和日历邀请发送。</p><h2 id="地址类型" tabindex="-1">地址类型 <a class="header-anchor" href="#地址类型" aria-label="Permalink to &quot;地址类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>适合场景</th><th>创建时填写</th></tr></thead><tbody><tr><td>普通地址</td><td>个人或业务固定邮箱，例如 <code>support@example.com</code></td><td>名称、地址前缀、域名</td></tr><tr><td>通配地址</td><td>接收同域名下未单独创建的地址</td><td>名称、通配地址、域名</td></tr><tr><td>群组</td><td>一个地址分发给多个成员</td><td>名称、群组地址、域名；保存后维护成员</td></tr><tr><td>转发地址</td><td>收到邮件后转发到外部邮箱</td><td>名称、代理地址、域名、转发地址</td></tr></tbody></table><p>创建地址时，左侧输入地址前缀，右侧从域名下拉中选择 <code>@domain</code>。编辑已有地址时，地址和域名不可改，只能改名称；转发地址还可以更新转发目标。</p><h2 id="地址列表" tabindex="-1">地址列表 <a class="header-anchor" href="#地址列表" aria-label="Permalink to &quot;地址列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td>Address</td><td>完整邮箱地址</td></tr><tr><td>Name</td><td>显示名称</td></tr><tr><td>Use For</td><td>地址类型标签</td></tr><tr><td>Remark</td><td>转发地址显示转发目标；群组显示成员数量</td></tr><tr><td>编辑签名</td><td>非通配地址可维护签名</td></tr><tr><td>编辑</td><td>修改名称，转发地址可修改转发目标</td></tr><tr><td>进入收件箱</td><td>跳到收件箱并按该地址筛选</td></tr><tr><td>删除</td><td>勾选一条或多条地址后删除</td></tr></tbody></table><p>删除默认地址后，页面会清空默认地址，需要重新选择。</p><h2 id="群组成员" tabindex="-1">群组成员 <a class="header-anchor" href="#群组成员" aria-label="Permalink to &quot;群组成员&quot;">​</a></h2><p>点击群组地址的成员标签，会打开群组成员弹窗。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>添加成员</td><td>点击加号，输入成员邮箱并保存</td></tr><tr><td>移除成员</td><td>点击成员行的 <code>Remove</code></td></tr><tr><td>校验</td><td>成员地址必须是有效邮箱，长度需符合校验规则</td></tr></tbody></table><p>群组适合 <code>team@example.com</code>、<code>support@example.com</code> 这类需要多人接收的地址。</p><h2 id="签名" tabindex="-1">签名 <a class="header-anchor" href="#签名" aria-label="Permalink to &quot;签名&quot;">​</a></h2><p>点击地址行的签名图标打开签名编辑器。签名使用富文本编辑器维护，保存后会在撰写页按发件人自动插入。</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td>新邮件</td><td>签名插入正文末尾</td></tr><tr><td>回复 / 转发</td><td>签名插入原邮件内容之前</td></tr><tr><td>多个发件地址</td><td>每个地址维护自己的签名</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>首次开通发信</td><td>确认域名 DNS -&gt; 新建普通地址 -&gt; 设置默认地址 -&gt; 写一封测试邮件</td></tr><tr><td>做客服组邮箱</td><td>新建群组 -&gt; 添加成员 -&gt; 进入收件箱检查收件</td></tr><tr><td>转发到外部系统</td><td>新建转发地址 -&gt; 填转发目标 -&gt; 发送测试邮件</td></tr><tr><td>准备外部客户端</td><td>设置默认地址 -&gt; <a href="./imap.html">IMAP</a> -&gt; 生成授权码</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./compose.html">撰写邮件</a></td><td>发件人和签名如何生效</td></tr><tr><td><a href="./imap.html">IMAP</a></td><td>默认地址和授权码</td></tr><tr><td><a href="./../console/domains.html">控制台：域名</a></td><td>域名和 DNS</td></tr><tr><td><a href="/kb-docs/zh/api/mail/">k.mail</a></td><td>业务发信 API</td></tr></tbody></table>',20))])}const f=e(s,[["render",i]]);export{_ as __pageData,f as default};
